function groupDeltaOnGrid(
  anchorStart: number,
  delta: number,
  snapStep: number | null,
  bounds: GroupMoveBounds,
): { requested: number; allowed: number } {
  if (snapStep === null) {
    const requested = roundTime(delta);
    return {
      requested,
      allowed: Math.min(bounds.maxDelta, Math.max(bounds.minDelta, requested)),
    };
  }
  return {
    requested: roundTime(snapTimeToGrid(anchorStart + delta, snapStep) - anchorStart),
    allowed: snapGroupDelta(anchorStart, delta, snapStep, bounds.minDelta, bounds.maxDelta),
  };
}

tool_input.new_string:
function groupDeltaOnGrid(
  anchor: ArrangementClip,
  delta: number,
  snapStep: number | null,
  group: { ids: readonly string[]; bounds: GroupMoveBounds },
  clips: readonly ArrangementClip[],
  laneTrackId: string,
): { requested: number; allowed: number } {
  const { bounds } = group;
  if (snapStep === null) {
    const requested = roundTime(delta);
    return {
      requested,
      allowed: Math.min(bounds.maxDelta, Math.max(bounds.minDelta, requested)),
    };
  }
  const targets = clipEdgeTargets(
    clips.filter((entry) => !group.ids.includes(entry.id)),
    anchor.id,
    laneTrackId,
  );
  return snapGroupMoveDelta(
    anchor.start,
    anchor.duration,
    delta,
    snapStep,
    bounds.minDelta,
    bounds.maxDelta,
    targets.startEdges,
    targets.endEdges,
  );
}
